item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; this does not establish whether it occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across repeated runs."
        }
      ],
      "instrument_review": "The task count, exact-grid scoring, and narrow intended comparison are specified. The score describes the reported run. Run consistency, puzzle selection, and conditions needed for fair system comparisons are insufficiently documented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "A single evaluation supplies no evidence of repeated-run stability; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "Exact-grid scoring and the grid-specific intended use make the reported score interpretable within its stated scope. The documented absence of repeated testing leaves consistency unassessed. Puzzle selection and fair comparison procedures remain unspecified."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations explicitly held the listed conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability criterion of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated runs support consistency under the listed fixed conditions and the report's explicit stability definition. This evidence supports the narrow grid-puzzle use; it does not establish consistency with different puzzles or settings. Puzzle selection and between-system comparison procedures remain unspecified."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers explicitly evaluated score variation across repeated runs under fixed listed conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability limit of two percentage points."
        }
      ],
      "instrument_review": "The repeated evaluations document substantial inconsistency under the listed conditions. Reporting 70% alone would inadequately describe the supplied findings. Comparisons should account for this variation; its cause and puzzle-selection procedures are not supplied."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not document repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence of score consistency beyond the single reported run."
        }
      ],
      "instrument_review": "Installation instructions explain setup, but add no evaluation evidence. Exact-grid scoring supports interpretation of the reported grid-puzzle result. Repeated-run consistency, puzzle selection, and conditions for fair comparisons remain insufficiently documented."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated grid puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison of general intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison matches the stated grid-specific use. Exact-grid scoring and fixed instructions support comparability, while other resource controls and repeated-run consistency are unspecified. The results support the reported performance difference, without establishing broader abilities."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported counts support A's better performance on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a cross-domain intended use does not supply evidence for a cross-domain conclusion."
        }
      ],
      "instrument_review": "The intended selection of greater general intelligence across domains exceeds the supplied grid-only evidence. Exact-grid scoring and fixed instructions support the narrow comparison, but broader task coverage, repeated-run consistency, and other controls for fair comparisons are not supplied."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence does not establish that assistance from A improves real workshop decisions compared with B."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports greater correctness with A in the studied workshop; the reported difference interval of 12 to 28 percentage points supports that direction."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "The trial provides no measured safety comparison; improved correctness alone does not establish improved safety."
        }
      ],
      "instrument_review": "The later preregistered randomized trial, new cases, blinded correctness checks, and reported uncertainty strengthen evidence for the intended workshop-specific choice. Its findings concern correctness in one workshop. Broader applicability, time benefits, and safety improvements remain unestablished; initial test construction and scoring details are limited."
    }
  ],
  "closing_note": "No material instructions were unclear. Missing evidence was classified as Not established; explicit conflicting evidence was classified as Contradicted."
}
